      a: a, tol: Math.abs(a) * 1e-6, fromUnit: fromU, toUnit: toU, unit: toU, inputValue: value, sizeRel: places > 0 ? 'toSmaller' : 'toBigger',
      q: fmtN(value) + ' ' + fromU + ' = ? ' + toU,
